function initSiteUI() {
  const header = document.querySelector('[data-site-header]');
  const menu = header?.querySelector('.site-menu');
  const updateHeader = () => header?.classList.toggle('scrolled', scrollY > 24);
  let scheduled = false;
  window.addEventListener('scroll', () => {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(() => { scheduled = false; updateHeader(); });
  }, { passive: true });
  updateHeader();
  menu?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => { menu.open = false; }));
  document.addEventListener('pointerdown', event => {
    if (document.querySelector('dialog[open]')) return;
    if (menu?.open && !menu.contains(event.target)) menu.open = false;
  });
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || !menu?.open || document.querySelector('dialog[open]')) return;
    menu.open = false;
    menu.querySelector('summary').focus();
  });
  const links = [...document.querySelectorAll('[data-section-link]')];
  const sections = [...new Set(links.map(link => document.getElementById(link.dataset.sectionLink)).filter(Boolean))];
  const hero = document.getElementById('top');
  if (hero) sections.unshift(hero);
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        links.forEach(link => {
          if (link.dataset.sectionLink === entry.target.id) link.setAttribute('aria-current', 'location');
          else link.removeAttribute('aria-current');
        });
      }
    }, { rootMargin: '-15% 0px -65% 0px' });
    sections.forEach(section => observer.observe(section));
  }

  const mode = resolveViewMode();
  document.documentElement.dataset.view = mode;
  document.querySelectorAll('[data-view-link]').forEach(link => {
    const url = new URL(link.href, location.href);
    url.searchParams.set('view', mode === 'static' ? '3d' : 'static');
    link.href = url.href;
    link.textContent = mode === 'static' ? 'Enable 3D' : 'Static view';
  });

  const feedback = document.querySelector('#copy-feedback');
  const fallback = document.querySelector('.copy-fallback');
  let timer, lastTrigger;
  function announce(message) {
    if (!feedback) return;
    clearTimeout(timer);
    feedback.textContent = message;
    feedback.classList.add('visible');
    timer = setTimeout(() => feedback.classList.remove('visible'), 4000);
  }
  document.querySelectorAll('[data-copy-email]').forEach(button => button.addEventListener('click', async () => {
    const email = button.dataset.copyEmail;
    lastTrigger = button;
    try {
      await navigator.clipboard.writeText(email);
      const label = button.querySelector('[data-copy-label]');
      if (label) {
        label.textContent = 'Copied ✓';
        setTimeout(() => { label.textContent = 'Copy email'; }, 3000);
      }
      announce('Email copied. Ready to paste.');
    } catch {
      if (fallback) {
        fallback.hidden = false;
        const input = fallback.querySelector('input');
        input.value = email;
        input.focus(); input.select();
      }
      announce('Select and copy the email, or use the email link.');
    }
  }));
  document.querySelector('[data-close-copy]')?.addEventListener('click', () => {
    fallback.hidden = true;
    lastTrigger?.focus({ preventScroll: true });
  });
}


// Source: js/dialogs.js
function initDialogs() {
  const dialogs = [...document.querySelectorAll('dialog')];
  const triggers = new WeakMap();
  const syncScroll = () => {
    const open = dialogs.some(dialog => dialog.open);
    document.documentElement.style.overflow = open ? 'hidden' : '';
    document.body.style.overflow = open ? 'hidden' : '';
    document.querySelector('.menu-toggle')?.setAttribute('aria-expanded', String(Boolean(document.querySelector('#mobile-menu[open]'))));
  };
  const close = dialog => { if (dialog?.open) dialog.close(); };
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    const active = dialogs.find(dialog => dialog.open);
    if (!active) return;
    event.preventDefault();
    close(active);
  });
  const open = (dialog, trigger = document.activeElement) => {
    if (!dialog || dialog.open) return;
    dialogs.filter(other => other.open).forEach(close);
    triggers.set(dialog, trigger);
    dialog.showModal();
    syncScroll();
  };
  for (const dialog of dialogs) {
    dialog.addEventListener('close', () => {
      syncScroll();
      if (dialog.id === 'lightbox') dialog.querySelector('img')?.removeAttribute('src');
      const trigger = triggers.get(dialog);
      queueMicrotask(() => {
        if (!dialogs.some(item => item.open) && trigger?.isConnected) trigger.focus({ preventScroll: true });
      });
    });
    dialog.addEventListener('click', event => {
      if (event.target !== dialog) return;
      const bounds = dialog.getBoundingClientRect();
      if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) close(dialog);
    });
    dialog.querySelectorAll('[data-close-dialog]').forEach(button => button.addEventListener('click', () => close(dialog)));
  }
  const menu = document.querySelector('#mobile-menu');
  document.querySelector('.menu-toggle')?.addEventListener('click', event => open(menu, event.currentTarget));
  menu?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => close(menu)));
  const wideScreen = matchMedia('(min-width: 801px)');
  wideScreen.addEventListener('change', event => { if (event.matches) close(menu); });
  const lightbox = document.querySelector('#lightbox');
  document.querySelectorAll('[data-lightbox]').forEach(link => link.addEventListener('click', event => {
    if (!lightbox) return;
    event.preventDefault();
    const source = link.querySelector('img');
    const caption = link.closest('figure')?.querySelector('figcaption');
    lightbox.querySelector('img').src = link.href;
    lightbox.querySelector('img').alt = source?.alt || 'Project image';
    lightbox.querySelector('figcaption').textContent = caption?.textContent || '';
    open(lightbox, link);
  }));
  return { open, close };
}


// Source: js/search.js
function initSearch(dialogs) {
  const dialog = document.querySelector('#search-dialog');
  const input = document.querySelector('#search-input');
  const results = document.querySelector('#search-results');
  const source = document.querySelector('#search-data');
  if (!dialog || !input || !results || !source) return;
  const entries = JSON.parse(source.textContent);
  let matches = entries;
  let active = 0;
  const empty = document.createElement('p');
  empty.className = 'search-empty';
  empty.setAttribute('role', 'status');
  empty.hidden = true;
  results.after(empty);
  function select(index) {
    active = index;
    const options = [...results.children];
    options.forEach((option, i) => option.setAttribute('aria-selected', String(i === active)));
    if (options[active]) {
      input.setAttribute('aria-activedescendant', options[active].id);
      options[active].scrollIntoView({ block: 'nearest' });
    } else input.removeAttribute('aria-activedescendant');
  }
  function render() {
    const query = input.value.trim().toLocaleLowerCase();
    matches = entries.filter(entry => !query || `${entry.title} ${entry.description} ${entry.category} ${entry.keywords || ''}`.toLocaleLowerCase().includes(query));
    results.replaceChildren();
    empty.hidden = matches.length !== 0;
    // Search text is always a text node. It never passes through an HTML parser.
    empty.textContent = `No results for “${input.value}”. Try Java, SSTC, AI or résumé.`;
    matches.forEach((entry, index) => {
      const option = document.createElement('a');
      option.className = 'search-result';
      option.id = `search-option-${index}`;
      option.href = entry.href;
      option.setAttribute('role', 'option');
      option.tabIndex = -1;
      const copy = document.createElement('div');
      const title = document.createElement('strong');
      const description = document.createElement('small');
      const badge = document.createElement('span');
      title.textContent = entry.title;
      description.textContent = entry.description;
      badge.textContent = entry.category;
      badge.className = 'mono';
      copy.append(title, description);
      option.append(copy, badge);
      option.addEventListener('click', () => dialogs.close(dialog));
      results.append(option);
    });
    select(0);
  }
  function open(trigger) {
    input.value = '';
    render();
    dialogs.open(dialog, trigger);
    input.focus();
  }
  document.querySelectorAll('.search-trigger').forEach(button => button.addEventListener('click', () => open(button)));
  document.addEventListener('keydown', event => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
      event.preventDefault();
      if (dialog.open) dialogs.close(dialog); else open(document.activeElement);
    }
  });
  input.addEventListener('input', render);
  input.addEventListener('keydown', event => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      if (matches.length) select((active + (event.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length);
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      results.children[active]?.click();
    }
  });
}


// Source: js/simulation.js
/** A teaching model of requests that all read the same single-seat snapshot. */
function reservationPlan({ guarded = true, requests = 5 } = {}) {
  if (!Number.isInteger(requests) || requests < 1) throw new RangeError('requests must be a positive integer');
  const outcomes = Array.from({ length: requests }, (_, i) => guarded && i > 0 ? 'conflict' : 'accepted');
  const accepted = outcomes.filter(outcome => outcome === 'accepted').length;
  return Object.freeze({ outcomes: Object.freeze(outcomes), accepted, conflicts: requests - accepted, oversold: accepted - 1, remaining: 0, version: guarded ? 2 : 1 });
}

function initSimulation() {
  const run = document.querySelector('#run-simulation');
  if (!run) return;
  const resetButton = document.querySelector('#reset-simulation');
  const result = document.querySelector('#simulation-result');
  const seatCount = document.querySelector('#seat-count');
  const versionCount = document.querySelector('#version-count');
  const rows = [...document.querySelectorAll('.request-row')];
  const modes = [...document.querySelectorAll('[data-locking]')];
  let guarded = true;
  let generation = 0;
  let pending = null;
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const delay = (duration, signal) => new Promise((resolve, reject) => {
    if (signal.aborted) return reject(new DOMException('Cancelled', 'AbortError'));
    const onAbort = () => { clearTimeout(timer); reject(new DOMException('Cancelled', 'AbortError')); };
    const timer = setTimeout(() => { signal.removeEventListener('abort', onAbort); resolve(); }, duration);
    signal.addEventListener('abort', onAbort, { once: true });
  });
  function reset() {
    generation++;
    pending?.abort();
    pending = null;
    run.disabled = false;
    run.firstChild.textContent = 'Run 5 requests ';
    seatCount.textContent = '1';
    versionCount.textContent = '1';
    rows.forEach(row => { row.removeAttribute('data-state'); row.querySelector('.worker-status').textContent = 'READY'; });
    result.textContent = guarded ? 'Ready. All five requests will read version 1.' : 'Ready. Every request will read one available seat, with no coordination.';
  }
  modes.forEach(button => button.addEventListener('click', () => {
    guarded = button.dataset.locking === 'true';
    modes.forEach(mode => mode.setAttribute('aria-pressed', String(mode === button)));
    reset();
  }));
  resetButton.addEventListener('click', reset);
  run.addEventListener('click', async () => {
    reset();
    const iteration = generation;
    const controller = new AbortController();
    pending = controller;
    run.disabled = true;
    run.firstChild.textContent = 'Requests in flight ';
    result.textContent = 'All requests read the same snapshot: one seat remaining, version 1.';
    const plan = reservationPlan({ guarded });
    const step = reduced.matches ? 0 : 100;
    try {
      for (const row of rows) {
        row.dataset.state = 'reading';
        row.querySelector('.worker-status').textContent = 'READ v1';
        await delay(step, controller.signal);
      }
      await delay(reduced.matches ? 0 : 300, controller.signal);
      for (const [index, row] of rows.entries()) {
        row.dataset.state = plan.outcomes[index];
        row.querySelector('.worker-status').textContent = plan.outcomes[index] === 'accepted' ? 'COMMITTED' : 'CONFLICT';
        await delay(step, controller.signal);
      }
      if (iteration !== generation) return;
      seatCount.textContent = String(plan.remaining);
      versionCount.textContent = String(plan.version);
      result.textContent = guarded
        ? '1 commit. 4 version conflicts. Only the first update matches version 1; the seat is allocated once.'
        : '5 accepted for 1 seat. Each stale write sets availability to zero, hiding 4 extra allocations.';
    } catch (error) {
      if (error.name !== 'AbortError') throw error;
    } finally {
      if (iteration === generation) {
        pending = null;
        run.disabled = false;
        run.firstChild.textContent = 'Run a fresh round ';
      }
    }
  });
  window.addEventListener('pagehide', () => pending?.abort(), { once: true });
}


